using System.ComponentModel.DataAnnotations;
using Dooja.Web.Data;
using Dooja.Web.Models;
using Dooja.Web.Services;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Authorization;
using Microsoft.EntityFrameworkCore;
namespace Dooja.Web.Controllers.Api;
[Route("api/owner"), Authorize(Roles = "Owner,Admin")]
public class OwnerController(DoojaDb db, BookingService service) : ApiBase(db)
{
    private IQueryable<Place> Places => Db.Places.Where(x => x.OwnerUserId == UserId || User.IsInRole("Admin"));
    private IQueryable<Booking> Bookings => Db.Bookings.Where(x => x.Place!.OwnerUserId == UserId || User.IsInRole("Admin"));
    [HttpGet("dashboard")] public async Task<IActionResult> Dashboard() { var today = BookingService.Today; return Ok(new { todayBookings = await Bookings.CountAsync(x => x.Day == today && x.Status != "ملغي"), todayIncome = await Bookings.Where(x => x.Day == today && (x.Arrived || x.Status == "مكتمل")).SumAsync(x => (long)x.Total), pending = await Bookings.CountAsync(x => x.Status == "بانتظار القبول"), places = await Places.CountAsync() }); }
    [HttpGet("places")] public async Task<IActionResult> MyPlaces() => Ok(await Places.AsNoTracking().ToListAsync());
    public record PlaceInput([Required, StringLength(150)] string Name, [Required] string Type, [Required] string Area, [Required] string Category, [Range(0, 100000000)] int Price, string Unit, string ImageKey, string Phone, [RegularExpression("open|slots|full")] string Kind);
    [HttpPost("places")] public async Task<IActionResult> CreatePlace(PlaceInput i) { var p = new Place { OwnerUserId = UserId, Name = i.Name, Type = i.Type, Area = i.Area, Category = i.Category, Price = i.Price, Unit = i.Unit, ImageKey = i.ImageKey, Phone = i.Phone, Kind = i.Kind }; Db.Places.Add(p); await Db.SaveChangesAsync(); return Ok(p); }
    [HttpPut("places/{id}")] public async Task<IActionResult> UpdatePlace(string id, PlaceInput i) { var p = await Places.FirstOrDefaultAsync(x => x.Id == id); if (p == null) return NotFound(); p.Name = i.Name; p.Type = i.Type; p.Area = i.Area; p.Category = i.Category; p.Price = i.Price; p.Unit = i.Unit; p.ImageKey = i.ImageKey; p.Phone = i.Phone; p.Kind = i.Kind; await Db.SaveChangesAsync(); return Ok(p); }
    [HttpGet("bookings")] public async Task<IActionResult> MyBookings(string? status) { var q = Bookings.AsNoTracking().Include(x => x.User).Include(x => x.Place).AsQueryable(); if (status != null) q = q.Where(x => x.Status == status); return Ok(await q.OrderByDescending(x => x.Id).Take(200).ToListAsync()); }
    public record StatusRequest([Required] string Status);
    [HttpPost("bookings/{id:int}/status")] public async Task<IActionResult> Status(int id, StatusRequest i) { var b = await Bookings.FirstOrDefaultAsync(x => x.Id == id); if (b == null) return NotFound(); var error = await service.SetStatus(b, i.Status); return error == null ? Ok(b) : BadRequest(new { error }); }
    [HttpPost("bookings/{id:int}/arrive")] public async Task<IActionResult> Arrive(int id) { var b = await Bookings.FirstOrDefaultAsync(x => x.Id == id); if (b == null) return NotFound(); if (b.Status != "مؤكد") return BadRequest(new { error = "الحجز غير مؤكد" }); b.Arrived = true; await Db.SaveChangesAsync(); return Ok(b); }
    [HttpGet("offers")] public async Task<IActionResult> Offers() => Ok(await Db.Offers.AsNoTracking().Where(x => x.Place!.OwnerUserId == UserId || User.IsInRole("Admin")).ToListAsync());
    public record OfferInput([Required] string PlaceId, [Required, StringLength(160)] string Title, string Disc, [Range(0, 100000000)] int NewPrice, [Range(0, 100000000)] int OldPrice, string ExpiryText, DateOnly? ExpiresOn, bool Active);
    [HttpPost("offers")] public async Task<IActionResult> CreateOffer(OfferInput i) { if (!await Owns(i.PlaceId)) return Forbid(); var p = await Db.Places.FindAsync(i.PlaceId); if (p == null) return NotFound(); var o = new Offer { PlaceId = p.Id, Title = i.Title, Disc = i.Disc, NewPrice = i.NewPrice, OldPrice = i.OldPrice, ExpiryText = i.ExpiryText, ExpiresOn = i.ExpiresOn, Active = i.Active, Area = p.Area, Category = p.Category, ImageKey = p.ImageKey }; Db.Offers.Add(o); await Db.SaveChangesAsync(); return Ok(o); }
    [HttpPut("offers/{id}")] public async Task<IActionResult> UpdateOffer(string id, OfferInput i) { var o = await Db.Offers.FindAsync(id); if (o == null) return NotFound(); if (!await Owns(o.PlaceId) || !await Owns(i.PlaceId)) return Forbid(); var p = await Db.Places.FindAsync(i.PlaceId); if (p == null) return NotFound(); o.PlaceId = p.Id; o.ImageKey = p.ImageKey; o.Area = p.Area; o.Category = p.Category; o.Title = i.Title; o.Disc = i.Disc; o.NewPrice = i.NewPrice; o.OldPrice = i.OldPrice; o.ExpiryText = i.ExpiryText; o.ExpiresOn = i.ExpiresOn; o.Active = i.Active; await Db.SaveChangesAsync(); return Ok(o); }
    [HttpPost("offers/{id}/toggle")] public async Task<IActionResult> ToggleOffer(string id) { var o = await Db.Offers.FindAsync(id); if (o == null) return NotFound(); if (!await Owns(o.PlaceId)) return Forbid(); o.Active = !o.Active; await Db.SaveChangesAsync(); return Ok(o); }
    [HttpGet("reviews")] public async Task<IActionResult> Reviews() => Ok(await Db.Reviews.AsNoTracking().Include(x => x.Place).Where(x => x.Place!.OwnerUserId == UserId || User.IsInRole("Admin")).OrderByDescending(x => x.Id).Take(200).ToListAsync());
    [HttpGet("services/{placeId}")] public async Task<IActionResult> Services(string placeId) { if (!await Owns(placeId)) return Forbid(); return Ok(await Db.OwnerServices.Where(x => x.PlaceId == placeId).ToListAsync()); }
    public record ServiceInput([Required] string PlaceId, [Required, StringLength(120)] string Name, [Range(0, 100000000)] int Price, [Required] string Unit);
    [HttpPost("services")] public async Task<IActionResult> AddService(ServiceInput i) { if (!await Owns(i.PlaceId)) return Forbid(); var s = new OwnerService { PlaceId = i.PlaceId, Name = i.Name, Price = i.Price, Unit = i.Unit }; Db.OwnerServices.Add(s); await Db.SaveChangesAsync(); return Ok(s); }
    [HttpPut("services/{id:int}")] public async Task<IActionResult> EditService(int id, ServiceInput i) { var s = await Db.OwnerServices.FindAsync(id); if (s == null) return NotFound(); if (!await Owns(s.PlaceId)) return Forbid(); s.Name = i.Name; s.Price = i.Price; s.Unit = i.Unit; await Db.SaveChangesAsync(); return Ok(s); }
    [HttpDelete("services/{id:int}")] public async Task<IActionResult> DeleteService(int id) { var s = await Db.OwnerServices.FindAsync(id); if (s == null) return NotFound(); if (!await Owns(s.PlaceId)) return Forbid(); Db.OwnerServices.Remove(s); await Db.SaveChangesAsync(); return NoContent(); }
    [HttpGet("closed-slots/{placeId}")] public async Task<IActionResult> Closed(string placeId) { if (!await Owns(placeId)) return Forbid(); return Ok(await Db.ClosedSlots.Where(x => x.PlaceId == placeId).ToListAsync()); }
    public record SlotInput([Required] string PlaceId, DateOnly Day, [Required, RegularExpression(@"(?:[01]\d|2[0-3]):[0-5]\d")] string Time);
    [HttpPost("closed-slots")] public async Task<IActionResult> CloseSlot(SlotInput i) { if (!await Owns(i.PlaceId)) return Forbid(); if (await Db.ClosedSlots.AnyAsync(x => x.PlaceId == i.PlaceId && x.Day == i.Day && x.Time == i.Time)) return Conflict(new { error = "الوقت مغلق مسبقاً" }); var c = new ClosedSlot { PlaceId = i.PlaceId, Day = i.Day, Time = i.Time }; Db.ClosedSlots.Add(c); await Db.SaveChangesAsync(); return Ok(c); }
    [HttpDelete("closed-slots/{id:int}")] public async Task<IActionResult> OpenSlot(int id) { var c = await Db.ClosedSlots.FindAsync(id); if (c == null) return NotFound(); if (!await Owns(c.PlaceId)) return Forbid(); Db.ClosedSlots.Remove(c); await Db.SaveChangesAsync(); return NoContent(); }
}
